// dissentPlanError is a validation failure with the code vocabulary above.
type dissentPlanError struct {
	Code    string
	Message string
}

func (err *dissentPlanError) Error() string { return err.Code + ": " + err.Message }

func dissentFail(code string, format string, args ...any) error {
	return &dissentPlanError{Code: code, Message: fmt.Sprintf(format, args...)}
}

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

type dissentConsequenceFacts struct {
	Production    *bool
	CustomerData  *bool
	MoneyMovement *bool
	Irreversible  *bool
	Regulated     *bool
}

func (facts dissentConsequenceFacts) get(name string) *bool {
	switch name {
	case "production":
		return facts.Production
	case "customerData":
		return facts.CustomerData
	case "moneyMovement":
		return facts.MoneyMovement
	case "irreversible":
		return facts.Irreversible
	case "regulated":
		return facts.Regulated
	}
	return nil
}

func (facts *dissentConsequenceFacts) set(name string, value *bool) {
	switch name {
	case "production":
		facts.Production = value
	case "customerData":
		facts.CustomerData = value
	case "moneyMovement":
		facts.MoneyMovement = value
	case "irreversible":
		facts.Irreversible = value
	case "regulated":
		facts.Regulated = value
	}
}

func (facts dissentConsequenceFacts) isTrue(name string) bool {
	value := facts.get(name)
	return value != nil && *value
}

func (facts dissentConsequenceFacts) canonical() map[string]any {
	out := map[string]any{}
	for _, name := range dissentConsequenceNames {
		if value := facts.get(name); value == nil {
			out[name] = nil
		} else {
			out[name] = *value
		}
	}
	return out
}

type dissentWorkContract struct {
	Version             string
	Objective           string
	Context             string
	AcceptanceCriteria  []string
	OutputFormat        string
	OutputInstructions  string
	Risk                string
	Consequences        dissentConsequenceFacts
	Reversible          *bool
	HumanReviewRequired bool
	Assurance           string
	Quality             string
	Modality            string
	Interaction         string
	Tools               string
	SideEffects         string
	DataClassification  string
	ProviderStorage     string
	ContextRetention    string
	EndToEndDeadlineMs  int
	Metadata            map[string]string
}

// canonical is the zod parse output shape (defaults applied) — what
// contractSha256 hashes.
func (contract dissentWorkContract) canonical() map[string]any {
	criteria := make([]any, 0, len(contract.AcceptanceCriteria))
	for _, item := range contract.AcceptanceCriteria {
		criteria = append(criteria, item)
	}
	metadata := map[string]any{}
	for key, value := range contract.Metadata {
		metadata[key] = value
	}
	var reversible any
	if contract.Reversible != nil {
		reversible = *contract.Reversible
	}
	return map[string]any{
		"version":             contract.Version,
		"objective":           contract.Objective,
		"context":             contract.Context,
		"acceptanceCriteria":  criteria,
		"output":              map[string]any{"format": contract.OutputFormat, "instructions": contract.OutputInstructions},
		"risk":                contract.Risk,
		"consequences":        contract.Consequences.canonical(),
		"reversible":          reversible,
		"humanReviewRequired": contract.HumanReviewRequired,
		"assurance":           contract.Assurance,
		"quality":             contract.Quality,
		"modality":            contract.Modality,
		"interaction":         contract.Interaction,
		"tools":               contract.Tools,
		"sideEffects":         contract.SideEffects,
		"dataPolicy":          map[string]any{"classification": contract.DataClassification, "providerStorage": contract.ProviderStorage, "contextRetention": contract.ContextRetention},
		"latency":             map[string]any{"endToEndDeadlineMs": float64(contract.EndToEndDeadlineMs)},
		"metadata":            metadata,
	}
}

